    B.SideBarData_0U5 = new A.SideBarData("HashRuns.org City Link", B.IconData_58280_MaterialIcons_null_false, "This link will bring you to our public website for run information for your city on www.hashruns.org.\r\n\r\nYour Kennel must be configured to work with HashRuns.org which you can set on the 'Other' tab here.\r\n\r\nYou can open or copy the link with these buttons.");
    B.IconData_QXe = new A.IconData(984969, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_0aW = new A.SideBarData("Website Enabled", B.IconData_QXe, "Toggle your kennel website on or off.\n\nWhen disabled, visitors will not be able to view your public website even if they have the URL.");
    B.IconData_PsI = new A.IconData(984564, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_1hX = new A.SideBarData("Run Name", B.IconData_PsI, 'Enter a descriptive name for this run. This will be displayed in run listings and calendars.\n\nGood examples: "Red Dress Run 2024", "Annual Pub Crawl", "Monthly Full Moon Hash".');
    B.IconData_zIC = new A.IconData(62038, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_1o9 = new A.SideBarData("Require RSVP for Extras", B.IconData_zIC, "When enabled, hashers must RSVP if they want the extras.\n\nThis helps with planning and ordering.");
    B.IconData_3UQ = new A.IconData(61809, "Foundation", "flutter_vector_icons", false);
    B.SideBarData_2a3 = new A.SideBarData("HashRuns.org Region Link", B.IconData_3UQ, "This link will bring you to our public website for run information for all kennels in your state, province or region on www.hashruns.org.\r\n\r\nYour Kennel must be configured to work with HashRuns.org which you can set on the 'Other' tab here.\r\n\r\nYou can open or copy the link with these buttons.");
    B.IconData_LLv = new A.IconData(986814, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_3MY = new A.SideBarData("Distance Preference", B.IconData_LLv, 'This setting determines if your Kennel will display distances in miles or kilometers.\n\nIt is probably best to keep this setting on the "Default for the Country" as Harrier Central will select the setting that is appropriate to the location you are in.');
    B.SideBarData_3Un = new A.SideBarData("Run Tags", B.IconData_CcM, "Select tags that describe this run.\n\nTags are organized into categories:\n\u2022 Theme (Normal run, Red Dress, Full Moon, etc.)\n\u2022 Restrictions (Men only, Women only, Kids allowed, etc.)\n\u2022 What to bring (Flashlight, Dry clothes, etc.)\n\u2022 Run Type (Pub crawl, Short trail, Long trail, etc.)\n\u2022 Terrain (Shiggy, City, Hills, etc.)\n\u2022 Hares (Live hare, Dead hare, etc.)\n\u2022 Other (On-After, Parking, etc.)");
    B.SideBarData_3mr = new A.SideBarData("Run Card Colour", B.IconData_nIy, "Background colour for run cards \u2014 the featured run and upcoming runs list (8-digit hex #RRGGBBAA recommended).\n\nLeave empty to use the card background colour.");
    B.IconData_M10 = new A.IconData(61585, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_4Xo = new A.SideBarData("Exclude from Leaderboard", B.IconData_M10, "When enabled, this kennel will be excluded from the global leaderboard rankings.\n\nSome kennels prefer not to participate in leaderboard comparisons.");
    B.IconData_dx2 = new A.IconData(61464, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_54E = new A.SideBarData("Street Address", B.IconData_dx2, "Enter the street address for the run location.\n\nInclude the street number and name. This field is optional for remote locations where only coordinates are available.");
    B.IconData_sUv = new A.IconData(62098, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_57U = new A.SideBarData("Is Counted Run", B.IconData_sUv, "When enabled, this run counts towards hasher statistics.\n\nDisable this for special events that should not be counted.");
    B.IconData_qoV = new A.IconData(61550, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_5vN = new A.SideBarData("Is Visible", B.IconData_qoV, "When enabled, this run will be visible to hashers.\n\nDisable this to hide the run from public view while you are still setting it up.");
    B.IconData_qua = new A.IconData(62052, "Entypo", "flutter_vector_icons", false);
    B.SideBarData_6JW = new A.SideBarData("Country", B.IconData_qua, "The name of the country where your Kennel is located.");
    B.IconData_gjR = new A.IconData(62139, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_6KY = new A.SideBarData("Contact Details", B.IconData_gjR, "JSON object with contact details shown on the website contact section.\n\nCan include email addresses, phone numbers, and social media links.");
    B.SideBarData_6x8 = new A.SideBarData("Enable Copy Web Link", B.IconData_7OR, "When enabled, users can copy a public web link to share your runs with others who may not have the app.\n\nThis is useful for promoting runs on social media.");
    B.IconData_Mam = new A.IconData(61771, "FontAwesome", "flutter_vector_icons", false);
    B.SideBarData_7OH = new A.SideBarData("City", B.IconData_Mam, "The name of the city where your Kennel is located. It should be between 3 and 50 characters long.");
    B.IconData_yeL = new A.IconData(62004, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_7hs = new A.SideBarData("Maximum Participants", B.IconData_yeL, "Set the maximum number of hashers allowed for this run.\n\nRegistration may be closed when this limit is reached.");
    B.IconData_ANN = new A.IconData(987939, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_8AQ = new A.SideBarData("Developer", B.IconData_ANN, "This page contains useful links that are specific to your Kennel and resources for software developers.\r\n\r\nCheck out our growing set of Application Programming Interfaces (APIs) that give you options to build your own tools using data in our Global Hash database.");
    B.SideBarData_8Wq = new A.SideBarData("Run End Date & Time", B.IconData_Wb8, "Set the date and time when this run is expected to end.\n\nThis is optional but helpful for hashers planning their day.");
    B.IconData_yud = new A.IconData(62787, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_9ZK = new A.SideBarData("Extras Price", B.IconData_yud, "Set the price for the optional extras.");
    B.IconData_no1 = new A.IconData(987028, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_BSh = new A.SideBarData("Website Address", B.IconData_no1, "If your Kennel has a website, please provide the URL to it here.\n\nThis will make it easy for Hashers to find your Kennel whether or not you use Harrier Central to post your runs.");
    B.IconData_TsV = new A.IconData(61850, "FontAwesome", "flutter_vector_icons", false);
    B.SideBarData_BwB = new A.SideBarData("WordPress Toolbox", B.IconData_TsV, "Download this WordPress plug-in to enhance your WordPress Hash webpage with live data from Harrier Central.\r\n\r\nChanges to runs made through the portal (and soon the app too) are instantly reflected on your website making Harrier Central your one-stop data platform for all of your Kennel's data.");
    B.IconData_ZeB = new A.IconData(983863, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_C7M = new A.SideBarData("URL Shortcode", B.IconData_ZeB, 'The short name used in the URL path for your kennel website (e.g. "lh3" \u2192 hashruns.org/lh3).\n\nThis is separate from the kennel\'s unique short name and can be omitted if you use the default path.');
    B.IconData_J8o = new A.IconData(61525, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_CQY = new A.SideBarData("Include Extra Charges", B.IconData_J8o, "Enable this if the run includes optional extra charges.\n\nExamples: dinner after the run, commemorative t-shirt, etc.");
    B.IconData_XS7 = new A.IconData(61641, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_CRa = new A.SideBarData("Extra Navigation Menus", B.IconData_XS7, "JSON array of extra navigation menu items to add to the website header.\n\nEach entry should include a label and URL. Leave empty to use the default navigation.");
    B.IconData_ByE = new A.IconData(61788, "FontAwesome5_Solid", "flutter_vector_icons", false);
    B.SideBarData_E0z = new A.SideBarData("Meta Description", B.IconData_ByE, "Shown in search engine result snippets beneath the page title (max 155 characters).\n\nWrite a short, compelling description that tells searchers what your kennel is about.");
    B.IconData_sfi = new A.IconData(983221, "MaterialCommunityIcons", "flutter_vector_icons", false);
    B.SideBarData_EFi = new A.SideBarData("Scroll Blur", B.IconData_sfi, "Blur effect intensity applied to the hero image as the user scrolls down (0\u2013100).\n\n0 = no blur. 100 = maximum blur (~40px CSS blur). The blur reaches its maximum when the hero logo fades out.");
    B.IconData_TQv = new A.IconData(984512, "MaterialCommunityIcons", "flutter_vector_icons", false);
